class Solution {
public:
    bool leadsToDestination(int n, vector<vector<int>>& edges, int source, int destination) {
        vector<vector<int>> adj(n);
        for (const auto& e : edges) {
            adj[e[0]].push_back(e[1]);
        }
        if (!adj[destination].empty()) return false;

        vector<int> state(n, 0);

        auto dfs = [&](auto& self, int u) -> bool {
            if (state[u] != 0) return state[u] == 2;
            if (adj[u].empty()) return u == destination;
            state[u] = 1;
            for (int v : adj[u]) {
                if (!self(self, v)) return false;
            }
            state[u] = 2;
            return true;
        };

        return dfs(dfs, source);
    }
};

class Solution {
    public boolean leadsToDestination(int n, int[][] edges, int source, int destination) {
        List<Integer>[] adj = new ArrayList[n];
        for (int i = 0; i < n; ++i) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
        }
        if (!adj[destination].isEmpty()) return false;

        int[] state = new int[n];
        return dfs(adj, state, source, destination);
    }

    private boolean dfs(List<Integer>[] adj, int[] state, int u, int destination) {
        if (state[u] != 0) return state[u] == 2;
        if (adj[u].isEmpty()) return u == destination;
        state[u] = 1;
        for (int v : adj[u]) {
            if (!dfs(adj, state, v, destination)) return false;
        }
        state[u] = 2;
        return true;
    }
}

var leadsToDestination = function(n, edges, source, destination) {
    const adj = Array.from({ length: n }, () => []);
    for (const [u, v] of edges) {
        adj[u].push(v);
    }
    if (adj[destination].length > 0) return false;

    const state = new Array(n).fill(0);

    const dfs = (u) => {
        if (state[u] !== 0) return state[u] === 2;
        if (adj[u].length === 0) return u === destination;
        state[u] = 1;
        for (const v of adj[u]) {
            if (!dfs(v)) return false;
        }
        state[u] = 2;
        return true;
    };

    return dfs(source);
};
